const form = $('Préparer la demande à Claude').first().json.form;
const text = ($input.first().json.content || []).map(c => c.text || '').join('');
const raw = text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1);
let a;
try { a = JSON.parse(raw); } catch (e) { throw new Error("Claude n'a pas renvoyé un JSON valide : " + e.message); }
// no em dash or en dash, ever
const clean = v => typeof v === 'string' ? v.replace(/\s*[\u2014\u2013]\s*/g, ', ') : Array.isArray(v) ? v.map(clean) : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, clean(x)])) : v;
a = clean(a);
for (const l of ['fr', 'en', 'ar']) if (!a[l] || !a[l].title || !Array.isArray(a[l].sections)) throw new Error('Langue manquante ou incomplète : ' + l);
const slugify = s => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 70);
const slug = { fr: slugify(a.slug && a.slug.fr || a.fr.title), en: slugify(a.slug && a.slug.en || a.en.title) };
slug.ar = slug.en;
const cats = { 'Vraies histoires': 'stories', 'Lieux': 'places', 'Prix et conseils': 'prices', 'Mariages': 'weddings' };
const svc = { 'Demande en mariage': ['proposal', 's-prop'], 'Mariage': ['wedding', 's-wed'], 'Mariage oriental / musulman': ['oriental', 's-wed'], 'Séance couple': ['couple', 's-couple'], 'Concert ou événement': ['concert', 's-event'] }[form['Séance liée']] || ['proposal', 's-prop'];
const date = new Date().toISOString().slice(0, 10);
const key = slug.en.slice(0, 40);
const post = { key, date, updated: date, category: cats[form['Catégorie']] || 'stories', service: svc[0], session: svc[1], cover: form['Photo de couverture'], slug };
for (const l of ['en', 'fr', 'ar']) post[l] = { title: a[l].title, short: a[l].short, desc: a[l].desc, intro: a[l].intro || [], sections: a[l].sections, tips: a[l].tips || [] };
const file = `WEBSITE/final-version/scripts/posts/${date}-${key}.json`;
const content = JSON.stringify(post, null, 2) + '\n';
return [{ json: { branch: `article/${date}-${key}`, file, title: a.fr.title, slugFr: slug.fr, base64: Buffer.from(content, 'utf8').toString('base64') } }];
